<script setup lang="ts">
import { onMounted, ref } from 'vue'; import AppState from '../../components/AppState.vue'; import { api } from '../../lib/api'; const data=ref<any>();const error=ref(false);onMounted(async()=>{try{data.value=await api('/api/v1/admin/system')}catch{error.value=true}})
